    generated_at timestamp with time zone,
    sent_at timestamp with time zone,
    CONSTRAINT acct_statement_batches_check CHECK ((period_end >= period_start)),
    CONSTRAINT acct_statement_batches_customer_filter_check CHECK ((customer_filter = ANY (ARRAY['open_balance'::text, 'overdue'::text, 'all_active'::text, 'selected'::text]))),
    CONSTRAINT acct_statement_batches_statement_type_check CHECK ((statement_type = ANY (ARRAY['balance_forward'::text, 'open_item'::text, 'transaction'::text]))),
    CONSTRAINT acct_statement_batches_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'generated'::text, 'sent'::text])))
);

